const event = $input.first().json.body || $input.first().json;
const data = event.data || {};
const message = data.message || data.whatsappInboundMessage || event.message || event.whatsappInboundMessage || {};
const profile = data.customerProfile || data.profile || {};
const type = String(message.type || 'text');
let content = message.text?.body || message.body || '';
if (type === 'interactive') content = message.interactive?.button_reply?.id || message.interactive?.list_reply?.id || '';
if (type === 'button') content = message.button?.text || '';
if (type === 'image') content = message.image?.caption || '[image]';
if (type === 'audio' || type === 'voice') content = '[voice note]';
return [{ json: { event_type: event.type || '', message_id: String(message.id || data.messageId || event.messageId || event.id || ''), phone: String(message.from || message.sender?.phone || data.from || event.from || ''), customer_name: String(profile.name || message.customerProfile?.name || ''), message_type: type, content: String(content), direction: 'inbound', sender: 'customer', ai_intent: '' } }];

const input = $('Extract Inbound Message').first().json;
const context = $('Retrieve Chat Context').first().json || {};
return [{ json: { customer_phone: input.phone, customer_name: input.customer_name, message: input.content, context } }];

const input = $('Extract Inbound Message').first().json;
const context = $('Retrieve Chat Context').first().json || {};
const text = String(input.content || '').trim();
const match = text.match(/^btn_(confirm|cancel):([A-Z0-9-]+)$/i);
let route = 'ai';
let response = null;
if (context.session && context.session.ai_enabled === false) route = 'staff';
else if (context.is_open === false) { route = 'response'; response = { customer_phone: input.phone, log_text: 'Pabbas is currently closed. Please try again during our opening hours.', outgoing: { type: 'text', text: { body: 'Pabbas is currently closed. Please try again during our opening hours.' } } }; }
else if (match) { route = match[1].toLowerCase(); }
else if (/^(hi|hello|hey|menu|start)$/i.test(text)) { route = 'response'; response = { customer_phone: input.phone, log_text: 'Hello! Tell me what you would like to order from Pabbas.', outgoing: { type: 'text', text: { body: 'Hello! Tell me what you would like to order from Pabbas.' } } }; }
return [{ json: { route, order_number: match ? match[2].toUpperCase() : null, customer_phone: input.phone, customer_name: input.customer_name, response } }];

const source = $('Build AI Order Request').first().json;
const context = source.context || {};
const raw = String($input.first().json.output || '').replace(/```json/gi, '').replace(/```/g, '').trim();
const norm = (v) => String(v || '').toLowerCase().replace(/\s+/g, ' ').trim();
const out = { customer_phone: source.customer_phone, customer_name: source.customer_name, action: 'reply', reply: 'Tell me what you would like to order.', order_type: 'delivery', items: [], total: 0, order_number: null };
const button = source.message.match(/^btn_(confirm|cancel):([A-Z0-9-]+)$/i);
if (button) { out.action = button[1].toLowerCase(); out.order_number = button[2].toUpperCase(); out.reply = ''; return [{ json: out }]; }
let parsed = null;
try { const a = raw.indexOf('{'); const b = raw.lastIndexOf('}'); if (a >= 0 && b > a) parsed = JSON.parse(raw.slice(a, b + 1)); } catch {}
if (!parsed || parsed.intent !== 'order') { out.reply = String(parsed?.reply || out.reply); return [{ json: out }]; }
const menu = new Map();
for (const line of (typeof context.menu === 'string' ? context.menu.split('\n') : [])) { const i = line.lastIndexOf('|'); if (i > 0) menu.set(norm(line.slice(0, i)), { name: line.slice(0, i).trim(), price: Number(line.slice(i + 1)) || 0 }); }
for (const candidate of (Array.isArray(parsed.items) ? parsed.items : [])) { const item = menu.get(norm(candidate?.name)); const quantity = Math.round(Number(candidate?.quantity)); if (!item || !Number.isInteger(quantity) || quantity < 1 || quantity > 50) { out.reply = !item ? 'That item is not on the current Pabbas menu.' : 'Please choose a quantity between 1 and 50.'; return [{ json: out }]; } out.items.push({ name: item.name, quantity, price: item.price }); }
if (!out.items.length) { out.reply = String(parsed.reply || out.reply); return [{ json: out }]; }
const open = context.open_order || null;
out.action = open ? 'amend' : 'create';
out.order_number = open?.order_number || null;
out.order_type = ['delivery', 'takeaway', 'dine-in'].includes(String(parsed.order_type || '').toLowerCase()) ? String(parsed.order_type).toLowerCase() : (open?.order_type || 'delivery');
out.total = out.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
out.reply = String(parsed.reply || '');
return [{ json: out }];

const validation = $('Validate Menu And Price').first()?.json || {};
const response = $input.first().json || {};
if (response.outgoing) return [{ json: response }];
const route = $('Route Inbound Message').first()?.json || {};
const row = Array.isArray(response) ? (response[0] || {}) : (response.order || response);
const phone = validation.customer_phone || route.customer_phone;
const action = validation.action || (route.route === 'confirm' ? 'confirm' : route.route === 'cancel' ? 'cancel' : 'reply');
const orderNumber = row.order_number || validation.order_number || route.order_number || '';
const items = Array.isArray(row.items_json) && row.items_json.length ? row.items_json : (validation.items || []);
const lines = items.map((item) => `${item.name} x${item.quantity}`).join('\n');
let text = validation.reply || 'Pabbas could not process that request.';
let interactive = null;
if (['create', 'amend'].includes(action)) {
  text = `${action === 'create' ? 'Order draft' : 'Order updated'}${orderNumber ? ` ${orderNumber}` : ''}:\n${lines}\nTotal: Rs ${Number(row.total ?? validation.total ?? 0).toFixed(2)}\n\nPlease confirm your order.`;
  if (orderNumber) interactive = { type: 'button', body: { text }, action: { buttons: [ { type: 'reply', reply: { id: `btn_confirm:${orderNumber}`, title: 'Confirm order' } }, { type: 'reply', reply: { id: `btn_cancel:${orderNumber}`, title: 'Cancel order' } } ] } };
} else if (action === 'confirm') {
  text = `Order ${orderNumber || ''} confirmation result: ${response.result || 'processed'}.`.trim();
} else if (action === 'cancel') {
  text = `Order ${orderNumber || ''} cancellation result: ${response.result || 'processed'}.`.trim();
}
const outgoing = interactive ? { type: 'interactive', interactive } : { type: 'text', text: { body: text } };
return [{ json: { customer_phone: phone, log_text: text, outgoing, ycloud_payload: { from: $env.YCLOUD_WHATSAPP_BUSINESS_NUMBER, to: phone, ...outgoing } } }];
